package com.shiphappens.logistics.service;
import com.shiphappens.logistics.dto.Requests; import com.shiphappens.logistics.entity.*; import com.shiphappens.logistics.mapper.ExternalOrderMapper; import com.shiphappens.logistics.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.Instant;
@Service public class IntegrationService { private final LogisticsService logistics; private final ExternalOrderMapper mapper; private final IntegrationRequestLogRepository logs; public IntegrationService(LogisticsService logistics,ExternalOrderMapper mapper,IntegrationRequestLogRepository logs){this.logistics=logistics;this.mapper=mapper;this.logs=logs;} @Transactional public Result submit(Requests.ExternalOrder request,String requestId){IntegrationRequestLog log=new IntegrationRequestLog();log.setRequestId(requestId);log.setIntegrationName("external-customer-api");log.setEndpoint("/api/v1/integrations/orders");log.setHttpMethod("POST");log.setExternalReference(request.externalOrderId());log.setRequestTimestamp(Instant.now());var existing=logistics.orderByExternalReference(request.externalOrderId());if(existing.isPresent()){LogisticsOrder order=existing.get();log.setSuccess(true);log.setHttpStatus(200);log.setResponseTimestamp(Instant.now());logs.save(log);return new Result(true,true,requestId,request.externalOrderId(),order.getOrderNumber(),null,order.getStatus().name());} Customer customer=logistics.customerByCode(request.customerCode());Shipment shipment=logistics.createOrder(mapper.toCreateOrder(customer,request),request.externalOrderId());log.setSuccess(true);log.setHttpStatus(201);log.setResponseTimestamp(Instant.now());logs.save(log);return new Result(true,false,requestId,request.externalOrderId(),shipment.getOrder().getOrderNumber(),shipment.getShipmentNumber(),shipment.getStatus().name());} public record Result(boolean success,boolean idempotent,String requestId,String externalOrderId,String orderId,String shipmentId,String status){} }
